def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string representing a nested parentheses string.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum nesting of 2.

    >>> parse_nested_parens('(()()) ((())) () ((())) ()')
    [2, 3, 1, 3]
    """
    stack = []
    result = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            while stack[-1] != '(':
                result.append(stack.pop())
            stack.pop()
        else:
            result.append(char)
    while stack:
        result.append(stack.pop())
    return result

